export const parallelismMeta={slug:'training/parallelism',title:'Distributed Training and Parallelism',description:'Split examples, state, tensors, context, layers or experts. Follow ownership, exact partial results and the communication needed to assemble them.',date:'2026-04-08',updated:'2026-10-18',tags:['parallelism','DDP','ZeRO','FSDP','TP','PP','CP','SP','expert parallelism','all-reduce','sharding','rooflines'],topicPath:['training'],kind:'dense-topic',prototype:true,visibility:'public',learningGoals:['Predict collectives from tensor shapes and ownership','Distinguish memory savings from communication and scheduling costs','Choose and validate a mixed parallel mesh against measured topology'],related:['models/moe','models/attention','training/objectives','execution/communication','execution/performance','execution/hardware']};
