const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"',`class="dense-table-wrap" tabindex="0" role="region" aria-label="${caption}"`).replace('<table>','<table style="min-width:640px">');
const ex=contractExample();
export function pipelinePresentation(tick=0){
  const f=pipelineFrame(4,6,tick);
  const desktop=f.cells.map((row,s)=>`<text x="4" y="${40+s*42}">S${s+1}</text>`+row.map(c=>`<rect x="${44+c.tick*65}" y="${20+s*42}" width="60" height="34" rx="5" class="${c.active?'pipeline-active':'pipeline-cell'}" opacity="${c.batch===null?.12:1}"/>${c.batch!==null?`<text x="${74+c.tick*65}" y="${42+s*42}" text-anchor="middle" style="fill:${c.active?'#251b25':'#e9e5ed'}">μ${c.batch+1}</text>`:''}`).join('')).join('');
  const mobile=f.cells.map((row,s)=>`<text x="${76+s*74}" y="18" text-anchor="middle">S${s+1}</text>`+row.map(c=>`<rect x="${42+s*74}" y="${32+c.tick*34}" width="66" height="28" rx="4" class="${c.active?'pipeline-active':'pipeline-cell'}" opacity="${c.batch===null?.12:1}"/>${c.batch!==null?`<text x="${75+s*74}" y="${50+c.tick*34}" text-anchor="middle" style="fill:${c.active?'#251b25':'#e9e5ed'}">μ${c.batch+1}</text>`:''}`).join('')).join('')+Array.from({length:f.clocks},(_,t)=>`<text x="22" y="${50+t*34}" text-anchor="middle">${t+1}</text>`).join('');
  const label=`Clock ${tick+1} of nine. Active microbatches: ${f.cells.flat().filter(c=>c.active).map(c=>`stage ${c.stage+1}, microbatch ${c.batch+1}`).join('; ')}`;
  return {desktop,mobile,label,clock:`${tick+1} / ${f.clocks}`};
}
const initialPipeline=pipelinePresentation();
const matrixLab=`<div id="matrix-animation" class="topic-scene" data-matrix-lab><h3>Split the contracted dimension; add the partial outputs</h3><p>A has shape 2 × 4. B has shape 4 × 2. Each rank receives two matching columns of A and rows of B.</p><label>Computation progress <input type="range" min="0" max="100" step="1" value="0" aria-label="Partial matrix multiplication progress"></label><div class="scene-grid"><figure><figcaption>Rank 0 · A[:,0:2] @ B[0:2,:]</figcaption><div class="mini-matrix" data-partial-zero>${values([[0,0],[0,0]])}</div></figure><figure><figcaption>Rank 1 · A[:,2:4] @ B[2:4,:]</figcaption><div class="mini-matrix" data-partial-one>${values([[0,0],[0,0]])}</div></figure></div><figure><figcaption data-matrix-caption>1 / Local work: neither rank has the complete product.</figcaption><div class="mini-matrix" data-matrix-result>${values([[0,0],[0,0]])}</div></figure><div class="dense-actions"><button type="button" data-play>Play</button><button type="button" data-reset>Replay</button></div><p class="topic-scenes-caption">A = [[1,2,3,4],[2,0,1,3]], B = [[1,0],[0,1],[1,1],[2,−1]]. Intermediate states add actual contracted-index terms, not interpolated measurements.</p></div>`;
const pipelineLab=`<div class="topic-scene" data-pipeline-lab><h3>Fill, useful work, drain</h3><p>Four stages, six microbatches, one unit of forward work per cell. Each microbatch moves one stage per clock.</p><label>Clock <output data-clock>${initialPipeline.clock}</output><input type="range" min="0" max="8" step="1" value="0" aria-label="Forward pipeline clock"></label><svg class="pipeline-desktop" viewBox="0 0 640 200" role="img" aria-label="${initialPipeline.label}">${initialPipeline.desktop}</svg><svg class="pipeline-mobile" viewBox="0 0 340 350" role="img" aria-label="${initialPipeline.label}">${initialPipeline.mobile}</svg><div class="scene-stats"><span>Utilization <output>66.7%</output></span><span>Idle fraction <output>33.3%</output></span></div><div class="dense-actions"><button type="button" data-play>Play</button><button type="button" data-reset>Replay</button></div><p class="topic-scenes-caption">Forward-only timing model: not a simulation of GPipe or 1F1B backward scheduling. No network latency or stage imbalance.</p></div>`;
const ringLab=`<div id="context-ring" class="topic-scene" data-context-ring><h3>Queries stay; key/value blocks move</h3><p>Four ranks, four equally sized blocks. Each rank keeps its original query positions at every clock. Inspect each arriving KV block with the original causal and padding masks.</p><label>Ring clock <output data-ring-clock>1 / 4</output><input type="range" min="0" max="3" step="1" value="0" aria-label="Context ring clock"></label><div class="scene-grid" data-ring-ranks>${ringFrame(4,0).map(r=>`<figure><figcaption>Rank ${r.rank} · fixed Q${r.queryOwner}</figcaption><p>Current KV${r.kvOwner}</p><small>Send → rank ${r.sendTo} · receive ← rank ${r.receiveFrom}</small></figure>`).join('')}</div><p data-ring-caption>Clock 1: each query block reads its local KV block first.</p><div class="dense-actions"><button type="button" data-play>Play</button><button type="button" data-reset>Replay</button></div><p class="topic-scenes-caption">Synthetic ownership trace, not measured network time. Rank 0 visits KV0 → KV3 → KV2 → KV1. Each rank visits every KV block once, but only permitted keys contribute. Keep the running softmax maximum, denominator and weighted sum from the equation above.</p></div>`;
export function parallelismReader(link){return topic(parallelismMeta,parallelSections,'A parallel strategy is a choice of who owns each value—and when other ranks need it.',`
<p>A large model creates several different bottlenecks. Its parameters may not fit on one device. Its activations may be too large. Its batch may need more compute. Its experts may receive uneven work. One acronym cannot solve all four problems.</p><p>Describe the tensor layout before choosing a collective. Then describe when each value is needed. This connects data, tensor, pipeline, context and expert parallelism into one system rather than a list of independent techniques.</p>
${section('layout','Start with ownership and shapes',`${table('What is partitioned?',['Strategy','Ownership split','Main consequence'],[['Data parallelism (DP)','Examples / tokens across replicas','Combine gradient contributions'],['ZeRO / FSDP','Optimizer, gradient and parameter state','Gather state when needed; reduce owned gradients'],['Tensor parallelism (TP)','Dimensions inside layer matrices','Assemble activations or partial sums'],['Sequence parallelism (SP)','Token rows at TP boundaries','Avoid replicated token-wise activations'],['Context parallelism (CP)','Long-sequence positions during attention','Make remote context or recurrent state available'],['Pipeline parallelism (PP)','Groups of layers','Send activations and gradients between stages'],['Expert parallelism (EP)','Expert modules','Dispatch and return routed token representations']])}<p>A training mesh can combine these dimensions. Process groups then have different members and responsibilities. A local rank number is not enough to describe ownership; record named mesh axes and tensor dimensions.</p>`)}
${section('data','Data parallelism and the global gradient',`<p>Ordinary DP keeps a full model replica on every rank. Each replica processes different examples. A synchronized update combines their gradient contributions so all replicas remain consistent.</p>${eq(String.raw`L_{\rm global}=\frac{\sum_r\mathrm{loss\_sum}_r}{\sum_r\mathrm{valid\_count}_r}`,'The global valid count must be positive. An average of rank-local means weights ranks, not necessarily tokens.')}
<p>Unequal valid-token counts require an explicit normalization. If the framework averages gradients across R ranks, a local summed loss can be scaled by R/global_count. Check the framework’s reduction convention before applying this rule.</p><p>Gradient accumulation increases work between synchronizations. Suppress intermediate reductions when the framework permits it. Preserve loss scaling across accumulated microbatches. In DDP, wrap intermediate forward and backward passes in ddp.no_sync(); the final pass synchronizes accumulated gradients. A synchronization context around backward alone does not suppress the forward pass’s synchronization setup.</p><p>DDP autograd hooks make gradient buckets ready during backward. Bucketed reductions can overlap communication with later backward computation. Small buckets start early but pay more startup costs. Large buckets reduce startup overhead but may leave a large communication tail. Measure the critical path rather than only total bytes.</p><p>Matching a single-device update requires matching initial weights, optimizer state and loss normalization. Random operations and floating-point reduction order can prevent bitwise equality even when the mathematical update agrees.</p><p>The statistically useful global batch size and the hardware-efficient local batch size are different constraints. Adding replicas shrinks local work if global batch stays fixed. Increasing global batch instead can change optimization. There is no universal “512 GPUs” boundary.</p>`)}
${section('state','ZeRO and sharded state',`<p>DP replicates state that does not need a full copy on every rank at every instant. ZeRO progressively partitions that state. Stage 1 shards optimizer state. Stage 2 also shards gradients. Stage 3 also shards parameters.</p>${table('Illustrative mixed-precision Adam storage per parameter per rank',['Strategy','Weights','Gradients','Master + two moments','Total'],[['Replicated','2 bytes','2 bytes','12 bytes','16 bytes'],['ZeRO-1','2','2','12/R','4 + 12/R'],['ZeRO-2','2','2/R','12/R','2 + 14/R'],['ZeRO-3','2/R','2/R','12/R','16/R']])}
<p>This example assumes BF16 model weights and gradients, an FP32 master weight and two FP32 Adam moments. The moments alone require eight bytes. The twelve-byte column includes the master weight. Different optimizers and gradient dtypes change the calculation.</p><p>These totals exclude activations, temporary gathers, communication buffers and allocator overhead. A model can fit by the persistent-state formula and still run out of memory during a layer gather.</p><p>FSDP is related to full parameter sharding, not an identical implementation of every ZeRO-3 schedule. It gathers a unit’s parameters before use and reduces gradients to their owners. Resharding after forward saves memory but can require another gather for backward.</p><p>Compare schedules, not stage numbers alone. A common full-shard step has forward and backward parameter gathers plus a gradient reduce-scatter. Holding parameters longer changes memory and communication. Prefetching can hide transfers while increasing peak live buffers.</p><h3 id="state-traffic">Count the whole step, not one phase</h3><p>Let V be the logical bytes of all model parameters. Assume gradients use the same bytes and use a bandwidth-dominated ring on R ranks.</p>${eq(String.raw`\begin{aligned}V_{\rm DP,rank}&\approx2\frac{R-1}{R}V\\V_{\rm full\ shard,rank}&\approx3\frac{R-1}{R}V\end{aligned}`,'DP: one gradient all-reduce. Full shard: two parameter all-gathers plus one gradient reduce-scatter. These are bytes sent per rank, not elapsed times.')}<p>This schedule moves about 50% more bytes than DP. ZeRO-1/2 schedules can instead retain roughly DP’s traffic volume. Different dtypes, retained parameters, accumulation and offload change the comparison. Equal gather-plus-scatter and all-reduce volumes describe one phase; they do not include an extra forward gather.</p>`)}
${section('tensor','Tensor parallelism: pair the projections',`<p>Consider an MLP XW<sub>up</sub>, followed by a pointwise nonlinearity and W<sub>down</sub>. Partition W<sub>up</sub> by output columns. Every rank computes a different set of intermediate features. The nonlinearity can remain local.</p><p>Partition W<sub>down</sub> by its matching input rows. Each rank produces a partial contribution to the final hidden vector. Sum those partial outputs with an all-reduce, or reduce-scatter if the next operation wants a sharded result.</p>${eq(String.raw`\begin{aligned}Y&=\phi(XW_{\rm up})W_{\rm down}\\&=\sum_r\phi(XW_{{\rm up},r})W_{{\rm down},r}\end{aligned}`,'The first projection is column-sharded and the second is row-sharded. This pairing avoids gathering the full expanded activation between them.')}
<p>For SwiGLU, gate and up projections must share matching feature partitions. For attention, ranks can own different heads and then sum output-projection contributions. GQA’s small KV-head count can limit a naive head partition; MQA has only one KV head. Implementations may replicate KV heads or use another layout.</p><p>TP creates frequent layer-level communication. Fast low-latency links often matter more here than for large overlapped DP reductions. Excessive TP can also produce small, inefficient matrix multiplications. Eight-way TP is a common configuration, not a law.</p>${matrixLab}`)}
${section('sequence','Sequence and context parallelism',`<p>SP and CP can both split a sequence dimension. Their names do not make them the same operation.</p><p>In the common TP-associated SP layout, each rank keeps some token rows with their full hidden width. Token-wise normalization and dropout run locally. An all-gather restores token rows before a projection that needs them. A reduce-scatter can restore sequence ownership after the paired projection.</p><p>SP reduces replicated activation storage around those boundaries. A token-wise activation of shape ${inlineMath(String.raw`[B,S,H]`)} becomes ${inlineMath(String.raw`[B,\frac{S}{p},H]`)} on each of p ranks. That activation uses about 1/p of the replicated storage when S divides evenly. This is not a 1/p reduction of all training memory.</p><p>An all-gather plus reduce-scatter has roughly one all-reduce’s ring byte volume for the same logical tensor; startup latency and overlap can still differ.</p><p>SP does not, by itself, solve attention across a partitioned long context. CP assigns different query positions to ranks while preserving the context each query can access.</p><p>A ring-attention CP implementation keeps query blocks on their owners and circulates key/value blocks. Rank i sends to rank i+1 and receives from rank i−1, with wraparound.</p><p>Asynchronous sends can overlap independent attention work; insufficient local compute or shared-link contention can still expose the transfer.</p><p>Moving KV blocks solves ownership. Combining their results must still preserve one softmax over all permitted keys. A block with more probability mass must contribute more, even when blocks have equal sizes.</p>
<details><summary>Worked example: why two block outputs cannot simply be averaged</summary><p>Use one query, two keys and scalar values. Both keys are visible; there is no dropout. Give the first key score ln(3) and value 8. Give the second key score 0 and value 0.</p>${table('Synthetic two-block example: not a performance measurement',['Block','Unnormalized mass','Block-only output','Share of global mass'],[['A','3','8','75%'],['B','1','0','25%']])}<p>Each block contains one key, so its local softmax assigns that key weight 1. Averaging the block outputs gives 4. The global output is instead ${inlineMath(String.raw`\frac{3\cdot8+1\cdot0}{3+1}=6`)}. Block-only outputs have discarded the information needed to choose the right weights.</p><p>The global denominator is 4, not the number of blocks. Keep the denominator and weighted numerator, then divide once. The next equation performs this combination with a shared exponential scale.</p></details>
<p>For one query row, ${inlineMath(String.raw`s_j=\frac{q^\top k_j}{\sqrt{d_{\rm head}}}`)} is the scaled score for visible key j. The query and key head width is d<sub>head</sub>; v<sub>j</sub> is the value vector. The running maximum m sets the exponential scale. The scalar ℓ sums scaled exponential weights; the vector u sums those weights times values. The incoming block has maximum m<sub>block</sub>. Primes mark the state after adding that block.</p>${eq(String.raw`\begin{aligned}m'&=\max(m,m_{\rm block})\\\ell'&=e^{m-m'}\ell+\sum_{j\in\rm block}e^{s_j-m'}\\u'&=e^{m-m'}u+\sum_{j\in\rm block}e^{s_j-m'}v_j\\\mathrm{output}&=\frac u\ell\end{aligned}`,'One row, vector-valued u, no attention dropout. Sum only visible keys. This online normalization links CP to FlashAttention’s blockwise accumulation; normalize only when ℓ>0.')}
<p>If a larger score arrives, the old sums use the wrong scale. Multiply both old sums by the same factor before adding the new block. The represented output stays unchanged by that rescaling.</p><p>In the example, the shared maximum is ln(3). Block B contributes weight ${inlineMath(String.raw`e^{0-\ln3}=\frac13`)}. The accumulated denominator is 4/3, the numerator is 8, and the output remains 6. Processing B first gives the same result in exact arithmetic. Finite-precision summation can differ slightly with block order. See ${cite('https://arxiv.org/html/2205.14135v2#A2.SS3','FlashAttention, Appendix B.3')} for the blockwise update and ${cite('https://arxiv.org/html/2310.01889v4#S3','Ring Attention, Section 3')} for distributed block ownership.</p>
<p>Initialize an empty row with ℓ=0 and u=0. Skip fully masked blocks; use a guarded first-valid-block update rather than evaluating exp(−∞−(−∞)). A row with no valid keys needs an explicit output policy, not division by zero.</p>${ringLab}<p>Causal attention only sees permitted earlier positions. Early and late query chunks have different work. Zigzag assignments can pair them to balance ranks while retaining original positions and visibility.</p><h3 id="causal-balance">Why pair early and late queries?</h3><p>Consider sixteen query positions, numbered 1–16, including each position’s own key. Query q has q valid keys. Eight ranks each own two queries.</p>${table('Synthetic causal workload: valid query–key pairs, not measured latency',['Rank','Contiguous queries','Valid pairs','Zigzag queries','Valid pairs'],causalOwnership(8).map(r=>[String(r.rank),r.contiguous.join(' + '),String(r.contiguousWork),r.zigzag.join(' + '),String(r.zigzagWork)]))}<p>Contiguous ownership ranges from 3 to 31 valid pairs per rank. Zigzag ownership gives every rank 17. Both assignments perform the same 136 valid pairs. Real kernels operate on blocks, with padding, triangular tiles and transfer costs; equal pair counts do not guarantee equal times. Query positions never change, so the causal mask remains intact.</p><p>Local-window layers exchange only the reachable neighborhood. Recurrent attention can require an associative state scan instead of circulating all KV.</p><p>CP’s benefit depends on communication volume, kernel overlap and sequence layout. It does not make arbitrary long contexts cheap. <a href="${link('models/attention')}">Attention: masks, recurrence and online softmax →</a></p>`)}
${section('pipeline','Pipeline parallelism and idle time',`<p>PP assigns groups of layers to different stages. A microbatch sends activations forward and activation gradients backward. Model state becomes smaller per stage, but the stages are dependent.</p><p>A pipeline must fill and drain. For an ideal equal-cost model with p stages and m microbatches, distinguish idle overhead relative to useful work from idle fraction of elapsed capacity.</p>${eq(String.raw`\begin{aligned}\text{Idle overhead}&=\frac{p-1}m\\\text{Idle fraction}&=\frac{p-1}{m+p-1}\\\text{Utilization}&=\frac m{m+p-1}\end{aligned}`,'A simplified balanced schedule model. Real forward/backward costs, transfers, imbalance and interleaving alter timings.')}${pipelineLab}
<p>GPipe’s all-forward/all-backward schedule retains many activations. A 1F1B schedule alternates forward and backward work after warmup, often reducing live activation storage. It does not remove every bubble.</p><p>Interleaved schedules give each physical stage multiple virtual layer chunks. With v virtual chunks per physical stage, ideal balanced interleaving can reduce the non-interleaved bubble by roughly 1/v. This assumes a compatible microbatch schedule and ignores transfer overhead. Smaller chunks send messages more often; 1/v is not a general measured speedup. Zero-bubble schedules can defer weight-gradient computation after the urgently needed activation gradient; this trades dependencies, memory and scheduling complexity.</p><h3 id="pipeline-payload">What crosses a stage boundary?</h3><p>A stage sends activations forward, then receives their gradients during backward. It does not send every parameter for each microbatch.</p>${eq(String.raw`V_{\rm boundary}\approx s_a b_\mu H+s_d b_\mu H`,'Unsharded boundary per microbatch: bμ tokens, hidden width H, sa bytes per activation element and sd bytes per gradient element. Omits metadata and protocol overhead.')}<p>Sequence or tensor sharding changes the boundary’s local shape. Check whether adjacent stages agree on ownership; a hidden gather or redistribution can erase expected savings.</p><p>Full-shard parameter gathers can repeat across pipeline microbatches. Keeping parameters live avoids some gathers but consumes memory. Choose the PP and sharding schedule together.</p><p>Equal layer counts do not imply equal stage times. Embeddings, output projection, loss and expert imbalance matter. The slowest stage constrains throughput. Increasing microbatch count at fixed global batch also makes each microbatch smaller, which can hurt matrix efficiency and overlap.</p><p>PP is especially useful for capacity and aggregate throughput. A single dependent request does not become faster merely because it crosses more stages. In inference, each stage still owns the KV cache for its layers.</p>`)}
${section('experts','Expert parallelism',`<p>EP assigns experts to ranks. The router selects experts for each token, so token representations must move to their owners. Experts compute locally. Outputs then return to the token’s original owner for combination.</p><p>The forward pass therefore commonly contains a dispatch all-to-all and a return all-to-all. Token counts vary by destination. The slowest loaded rank can determine the layer’s completion time even if average FLOPs look low.</p><p>Load-balancing objectives, capacity policies, dropless routing and redundant expert copies change both learning and traffic. Redundancy needs a logical parameter owner or correctly synchronized replicas; copying experts without an update policy changes the model.</p><p>Grouped GEMMs improve execution of many small expert batches. Dispatch/computation overlap helps only when resources and buffer lifetimes permit it. Top-k routing multiplies token-expert assignments, not necessarily every tensor byte in the same way.</p><p>Do not use a universal E/k performance multiplier. Expert width, token count, load distribution and network placement determine the actual compute-to-communication ratio. <a href="${link('models/moe')}">Mixture of Experts: routing, balancing and stability →</a></p>`)}
${section('collectives','Infer communication from matrix layouts',`<p>Write C[I,K] = A[I,J]B[J,K]. J is contracted. I and K survive in the output. A sharding decision can split an output dimension or split the sum itself.</p>${table('Four cases that explain many parallel layers',['Layout','Local result','Required reconciliation'],[['I split over X; K split over independent Y','A valid output tile','None for that tile'],['J split on one operand only','The other operand does not yet match','Gather the shard, or slice the other operand and later reduce; compare gathered-input and reduced-output bytes'],['Matching J slices on both operands','A partial sum for every owned output','All-reduce, or reduce-scatter into an output layout'],['I and K both split over the same X','Only rank-matched tiles','Gather or redistribute to obtain missing cross-rank pairings']])}
<p>All-gather removes a partition by collecting shards. All-reduce sums partial contributions and replicates the result. Reduce-scatter sums contributions and leaves different result shards on different ranks. All-to-all redistributes ownership, often switching which tensor dimension is partitioned.</p><p>The backward operation must respect the transpose of the forward linear communication. An all-gather’s adjoint is a summing reduce-scatter; a summing reduce-scatter’s adjoint is an all-gather. If the implementation averages instead, account for that scaling explicitly.</p><h3 id="mesh-notation">A shape is not an ownership description</h3><p>Use a subscript for a named mesh axis. The global shape stays unchanged; the local shape depends on which dimensions that axis partitions.</p>${eq(String.raw`\begin{aligned}A[I_X,J]&:\quad\text{local shape }[\frac{I}{X},J]\\A[I,J_X]&:\quad\text{local shape }[I,\frac{J}{X}]\\C[I,K]\{U_X\}&:\quad\text{local shape }[I,K],\quad C=\sum_{x=1}^{X}C_x\end{aligned}`,'Assume divisible dimensions. An unsubscripted dimension is replicated over that mesh axis. UX marks an unreduced partial sum, not a different output dimension.')}<p>A batching dimension is retained in both inputs and the output. For example, each batch in C[b,I,K] = A[b,I,J]B[b,J,K] has its own product; b is not contracted. Two operands can have correct local dimensions yet incompatible ownership. In the table above, sharding I and K over the same axis leaves only diagonal rank-pair tiles, not the full product.</p><p>For a large ring collective on R ranks and a logical tensor of V bytes, each rank transfers approximately (R−1)V/R for all-gather or reduce-scatter. An all-reduce uses roughly twice that volume. Latency and topology still affect elapsed time. The Scaling Book’s ideal bandwidth-bound bidirectional ring gives about one quarter of the all-gather time for an all-to-all layout exchange. This is not a universal collective law. Its bandwidth convention differs from the unidirectional ring volume estimate above.</p><pre><code># Contract-axis sharding, two ranks, matching slices.
partial = A_local @ B_local  # [I, K], not the final product
dist.all_reduce(partial, op=dist.ReduceOp.SUM)
# Every rank now has C. Use reduce_scatter if C should stay sharded.</code></pre><p>The animation above performs this exact calculation. Named dimensions and local shapes often reveal a missing collective before a distributed run starts.</p>`)}
${section('topology','Map communication onto the machine',`<p>Separate a tightly connected scale-up domain from a slower scale-out network. A scale-up domain is not always identical to one host. NIC placement, rails and oversubscription determine which rank pairs can communicate efficiently.</p>${eq(String.raw`T_{\rm comm}\approx n_{\rm phases}\alpha+\frac{V_{\rm link}}{W_{\rm achieved}}`,'α is startup latency per phase. Vlink is traffic on the critical link. W is achieved bandwidth, not an advertised aggregate device figure.')}
${table('Four different bandwidth questions',['Quantity','What it limits','Common mistake'],[['Device memory bandwidth','Local weight and activation reads','Treating HBM bandwidth as network bandwidth'],['Scale-up link bandwidth','Frequent communication inside a fast domain','Using a chip’s summed links as one pair’s bandwidth'],['Node network egress','Traffic shared across a host’s NICs','Giving every GPU the full node NIC capacity'],['Fabric bisection bandwidth','Simultaneous traffic across groups of nodes','Assuming all NICs can sustain full rate together']])}<p>Frequent TP collectives often belong on fast local links. EP benefits from bisection bandwidth because many destinations are active together. DP/FSDP can sometimes tolerate scale-out links through larger work units and overlap. PP often sends smaller activation payloads across stages. These are starting hypotheses, not mandatory mappings.</p><p>Hierarchical collectives can exploit node-local bandwidth before crossing the fabric. Network-assisted reduction systems such as SHARP can accelerate supported reductions, but it does not accelerate arbitrary all-to-all routing automatically.</p><p>One accelerator link, summed scale-up links per accelerator, summed NIC bandwidth per node and achieved application bandwidth are four different measurements. A collective can achieve less than the advertised hardware rate. Benchmark the real group sizes and payloads.</p><p>Two operations can overlap in the schedule yet compete for the same link. CPU offload, checkpoint I/O, DP reductions and EP transfers all create contention. Measure node egress, fabric bisection and the slowest rank, not only average accelerator utilization.</p>`)}
${section('rooflines','How much work can hide communication?',`<p>Communication becomes harder to hide when local compute shrinks. Use consistent units: C in FLOP/s, W in byte/s, and communication volume in bytes.</p>${eq(String.raw`\begin{aligned}T_{\rm compute}&\approx\frac{\kappa P b}C\\T_{\rm DP}&\approx\frac{2s_gP(R-1)}{RW}\\b&\gtrsim\frac{2s_g}{\kappa}\frac{R-1}R\frac CW\end{aligned}`,'Illustrative dense model: P parameters, b local tokens, κ FLOPs per parameter per token, sg gradient bytes per parameter. Ignores latency, overlap details and activation costs.')}
<p>The parameter count cancels in this simplified DP threshold. Local work still has to be large enough relative to network arithmetic intensity. Attention at long context, sparse MoE compute and different precision can invalidate the dense approximation.</p><p>FSDP moves weights. TP moves activations. Their costs respond differently to a mixed mesh. Let ${inlineMath(String.raw`N=XY`)} devices, with X the FSDP degree and Y the TP degree. In a simplified forward MLP model, the two traffic terms vary approximately as ${inlineMath(String.raw`X`)} and ${inlineMath(String.raw`\frac1X`)} after substituting ${inlineMath(String.raw`Y=\frac NX`)}.</p>${eq(String.raw`X^*=\sqrt{\frac BF\frac{M_X}{M_Y}N},\qquad Y^*=\frac N{X^*}`,'B is global token count, F is expanded MLP width. MX and MY are effective mesh bandwidth multiplicities in the source model. This balances two communication times under full mutual overlap.')}
<p>The expression is a continuous candidate, not a deployable mesh. Round to valid hardware divisors and benchmark nearby configurations. The derivation assumes an MLP-dominated forward pass and a particular topology model. It does not predict every GPU cluster or long-context model.</p><h3 id="mixed-mesh-intensity">Why mixing the axes helps</h3>${eq(String.raw`\begin{aligned}\frac{T_{\rm math}}{T_{\rm comm}}&=\frac{\sqrt{BF}\sqrt{M_XM_Y}}{\alpha\sqrt N},\qquad\alpha=\frac CW\\\frac BN&>\frac{\alpha^2}{M_XM_YF}\end{aligned}`,'Scaling Book’s balanced continuous forward-MLP model, with its matched FLOP/byte constants and full mutual overlap. The inequality is the model’s compute-bound condition, not a hardware-independent batch prescription.')}<p>At the balanced split, doubling global token count improves this compute/communication ratio by only a square-root factor. Pure DP’s simplified ratio grows linearly with local token count. Mixing axes can support smaller local batches, but does not remove the communication limit.</p><p>For TP alone, a common rough limit is ${inlineMath(String.raw`Y<\frac{FW}{C}`)}, with byte and FLOP constants understood. Too many tensor shards create less local math without removing every activation collective. Preserve those constants when comparing dtypes or hardware.</p><p>Collective-GEMM overlap works tile by tile. It requires available compute, communication resources and enough local tile work. Double buffering also requires enough memory and correct buffer lifetimes. Merely launching transfers asynchronously does not prove that their cost disappears.</p>`)}
${section('reports','Architecture changes the distributed system',`<p>Model architecture changes the best distributed layout. These reported configurations are examples, not prescriptions. Follow the linked recipe sections for their conditions and evidence.</p>${table('Examples of model–system co-design',['Report','Specific distributed consequence'],[['Llama 3','TP/CP/PP/DP mesh; eight-GPU local TP, interleaved PP and stage balancing; all-gather CP benefits from small GQA KV tensors'],['Gemma 4','4,096–12,288 TPU chips; sharded state and multi-pod reductions; slice-level elasticity keeps useful work running after a localized failure'],['GLM-5','Pipeline-aware ZeRO-2 buffers, deferred weight gradients, vocabulary chunking, activation offload and hierarchical EP all-to-all'],['Kimi K3','Associative context parallelism for recurrent attention; dynamically redundant experts and routing plans for EP'],['MAI-Thinking-1','Descriptive sharding annotations require explicit communication; FP32 DP reductions are part of the mixed-precision recipe'],['MiMo-V2.6','128-token local windows reduce reachable KV exchange at million-token context; periodic global layers retain global retrieval'],['DeepSeek-V4.1','Shared indexers and memory cross pipeline boundaries; one logical owner, synchronized shadows and microbatch-scoped state; row-sharded Engram tables permit prefetch']])}
<p>These examples explain why architecture and distributed execution need joint design. Recurrent attention, cross-layer state sharing and memory tables create different dependencies from an ordinary independent stack of dense blocks. A mesh that worked for one model is not a plug-in recipe for the next.</p><p>Complete source reports: ${['deepseek-v4-1-flash','gemma-4-technical-report','glm-5-agentic-engineering','kimi-k3-open-frontier-intelligence','mai-thinking-1-building-a-hill-climbing-machine','mimo-v2-6-scaling-rl-towards-self-improvement','the-llama-3-herd-of-models'].map(s=>`<a href="${link(s==='deepseek-v4-1-flash'?'training/frontier-recipes#deepseek-run':s==='kimi-k3-open-frontier-intelligence'?'training/frontier-recipes#kimi-evidence':s==='glm-5-agentic-engineering'?'training/frontier-recipes#glm-run':s==='gemma-4-technical-report'?'models/compact-recipes#gemma-training':s==='mai-thinking-1-building-a-hill-climbing-machine'?'training/frontier-recipes#mai-systems':s==='the-llama-3-herd-of-models'?'training/frontier-recipes#llama-system':s==='mimo-v2-6-scaling-rl-towards-self-improvement'?'training/frontier-recipes#mimo-system':'ai/architectures/model-reports/'+s)}">${s.replaceAll('-',' ')} →</a>`).join(' · ')}.</p>`)}
${section('checks','Reproduction and debugging',`<ol class="dense-checklist"><li><b>Ownership.</b> Record global/local shapes, mesh axes, replicated values and logical parameter owners.</li><li><b>Exactness.</b> Compare a tiny distributed step against an unsharded reference, including masks and global loss normalization.</li><li><b>Updates.</b> Verify tied/shared parameters, optimizer states, gradient sums and accumulation scaling.</li><li><b>Memory.</b> Measure persistent state and peak temporary buffers separately.</li><li><b>Scheduling.</b> Check dependencies, buffer lifetimes and slowest-stage/rank timing.</li><li><b>Communication.</b> Measure startup, achieved bandwidth, overlap and critical-link contention.</li><li><b>Recovery.</b> Verify checkpoint ownership, resumability and mesh reconfiguration.</li></ol><p>Start with two ranks and tiny matrices. Many errors are layout or normalization mistakes rather than kernel failures. Inspect the compiler/runtime trace for hidden reshards between regions. Start the mesh design from a statistically justified global batch, not the device count. Increase scale only after the numerical reference and ownership model agree.</p>`)}
${section('sources','Sources and connected notes',`<p>${cite('https://jax-ml.github.io/scaling-book/sharding/','Scaling Book: sharded matrices')} · ${cite('https://jax-ml.github.io/scaling-book/training/','Scaling Book: training')} · ${cite('https://jax-ml.github.io/scaling-book/gpus/','Scaling Book: GPUs')} · ${cite('https://jax-ml.github.io/scaling-book/transformers/','Scaling Book: transformer costs')}</p><p>${cite('https://arxiv.org/abs/1910.02054','ZeRO')} · ${cite('https://arxiv.org/abs/1909.08053','Megatron-LM')} · ${cite('https://arxiv.org/abs/2205.05198','Reducing activation recomputation')} · ${cite('https://arxiv.org/abs/1811.06965','GPipe')} · ${cite('https://arxiv.org/abs/1806.03377','PipeDream')} · ${cite('https://docs.pytorch.org/docs/stable/generated/torch.nn.parallel.DistributedDataParallel.html','PyTorch DDP: synchronization')}</p><div class="dense-related"><a href="${link('models/moe')}">MoE →</a><a href="${link('models/attention')}">Attention →</a><a href="${link('training/objectives')}">Loss reductions →</a><a href="${link('execution/communication')}">GPU communication →</a><a href="${link('execution/performance')}">Compute and memory roofs →</a><a href="${link('execution/hardware')}">GPU infrastructure →</a></div>`)}
`);}
parallelismMeta.searchText=parallelismReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountParallelism(scope=document){mountTopic(scope,parallelismMeta.slug,article=>{
  const ring=article.querySelector('[data-context-ring]');rangePlayback(article,ring,v=>{
    const tick=Math.round(v),rows=ringFrame(4,tick);
    ring.querySelector('[data-ring-clock]').textContent=`${tick+1} / 4`;
    ring.querySelector('[data-ring-ranks]').innerHTML=rows.map(r=>`<figure><figcaption>Rank ${r.rank} · fixed Q${r.queryOwner}</figcaption><p>Current KV${r.kvOwner}</p><small>Send → rank ${r.sendTo} · receive ← rank ${r.receiveFrom}</small></figure>`).join('');
    ring.querySelector('[data-ring-caption]').textContent=tick===0?'Clock 1: each query block reads its local KV block first.':tick===3?'Clock 4: every rank has visited every KV block. Normalize the accumulated output, not each block independently.':`Clock ${tick+1}: query owners stay fixed; KV blocks have moved ${tick} hop${tick===1?'':'s'}. Apply masks before accumulating.`;
  },8000);
  const matrix=article.querySelector('[data-matrix-lab]');rangePlayback(article,matrix,v=>{const step=Math.min(4,Math.floor(v/20));const p0=step>=1?ex.partial0:[[0,0],[0,0]],p1=step>=2?ex.partial1:[[0,0],[0,0]];matrix.querySelector('[data-partial-zero]').innerHTML=values(p0);matrix.querySelector('[data-partial-one]').innerHTML=values(p1);matrix.querySelector('[data-matrix-result]').innerHTML=(step>=3?ex.result:[[0,0],[0,0]]).flat().map(v=>`<span class="${step>=3?'matrix-sum':''}">${v}</span>`).join('');matrix.querySelector('[data-matrix-caption]').textContent=['1 / Inputs assigned. Local outputs are not computed yet.','2 / Rank 0 computes its partial product.','3 / Both partial products exist: each is incomplete.','4 / Sum matching entries: the full product is [[12,1],[9,−2]].','5 / All-reduce replicates the full product on both ranks.'][step];},12000);
  const pipeline=article.querySelector('[data-pipeline-lab]');rangePlayback(article,pipeline,v=>{
    const scene=pipelinePresentation(Math.round(v));
    pipeline.querySelector('[data-clock]').textContent=scene.clock;
    pipeline.querySelector('.pipeline-desktop').innerHTML=scene.desktop;
    pipeline.querySelector('.pipeline-mobile').innerHTML=scene.mobile;
    for(const svg of pipeline.querySelectorAll('svg'))svg.setAttribute('aria-label',scene.label);
  },9000);
});}
